const INSTANCES=["https://inv.nadeko.net","https://invidious.nerdvpn.de","https://yt.chocolatemoo53.com","https://invidious.tiekoetter.com","https://invidious.f5.si"];
function id(value=""){if(!value.includes("/")&&!value.includes("?"))return value;try{const url=new URL(value,"https://www.youtube.com");return url.searchParams.get("v")||url.pathname.split("/").filter(Boolean).pop()||"";}catch{return value.replace(/^\/watch\?v=/,"").split("&")[0];}}
async function getStream({link,signal,providerContext}){const videoId=id(link);if(!videoId)return[];for(const host of INSTANCES){try{const data=(await providerContext.axios.get(`${host}/api/v1/videos/${encodeURIComponent(videoId)}`,{signal,timeout:15000})).data||{};const streams=[];const hls=data.hlsUrl||data.hls;if(typeof hls==="string"&&hls.length)streams.push({server:"Invidious HLS",link:hls,type:"m3u8",quality:"Auto"});const sources=[...(Array.isArray(data.formatStreams)?data.formatStreams:[]),...(Array.isArray(data.adaptiveFormats)?data.adaptiveFormats:[]),...(Array.isArray(data.videoStreams)?data.videoStreams:[])],seen=new Set;for(const source of sources){const url=source?.url,mime=String(source?.type||source?.mimeType||source?.mime||"").toLowerCase(),isVideo=mime.includes("video/")||mime.includes("video")||source?.qualityLabel||source?.quality,isMp4=mime.includes("video/mp4")||/\.mp4(?:$|[?&])/i.test(url||"")||source?.container==="mp4"||source?.format==="MPEG-4";if(url&&isVideo&&isMp4&&!seen.has(url)){seen.add(url);streams.push({server:"Invidious MP4",link:url,type:"mp4",quality:source.qualityLabel||source.quality||source.resolution||"Auto"});}}if(streams.length)return streams;}catch{}}return[];}exports.getStream=getStream;
